else{try{$s=$pdo->prepare("INSERT INTO users(name,email,password) VALUES(?,?,?)");$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);$_SESSION['user']=['id'=>(int)$pdo->lastInsertId(),'name'=>$name,'email'=>$email,'role'=>'customer'];redirect('index.php');}catch(PDOException $e){$error='Este e-mail já está cadastrado.';}}}
$pageTitle='Criar conta';include 'includes/header.php';?>
